def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None


def parse_int(text, default=0):
    try:
        return int(text)
    except ValueError:
        return default


def process_items(items, processor):
    results = {}
    for item in items:
        try:
            results[item] = processor(item)
        except Exception as e:
            results[item] = f"error: {e}"
    return results
